package com.example.takura.operations.controller;
import com.example.takura.identity.domain.StaffPrincipal; import com.example.takura.operations.application.SettingsService; import com.example.takura.operations.application.SettingsService.Update; import com.example.takura.identity.controller.StaffRequestPrincipal;
import java.util.*; import org.springframework.http.ResponseEntity; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/admin/settings") class SettingsController {private final SettingsService service;SettingsController(SettingsService s){service=s;}@GetMapping List<?> list(@StaffRequestPrincipal StaffPrincipal p){return service.list(p);}@PutMapping("/{id}")ResponseEntity<?> update(@StaffRequestPrincipal StaffPrincipal p,@PathVariable UUID id,@RequestHeader(value="If-Match",required=false)String m,@RequestBody Update r){if(m==null)return ResponseEntity.status(428).build();var v=service.update(p,id,Long.parseLong(m.replace("\"","")),r);return ResponseEntity.ok().eTag('"'+Long.toString(v.revision())+'"').body(v);}}
